-- Laci schema for MySQL 8. Generated by `pnpm --filter @lacijs/mysql schema`;
-- do not edit by hand. Equivalent to `MySqlStore#migrate()` with the default prefix.

CREATE TABLE IF NOT EXISTS laci_migrations (
  version     INT          NOT NULL PRIMARY KEY,
  name        VARCHAR(100) NOT NULL,
  applied_at  DATETIME(3)  NOT NULL DEFAULT (UTC_TIMESTAMP(3))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

-- 1: initial schema
CREATE TABLE IF NOT EXISTS laci_entries (
  id           BINARY(16)   NOT NULL PRIMARY KEY,
  `key`        VARCHAR(191) NOT NULL,
  kind         VARCHAR(20)  NOT NULL,
  environment  VARCHAR(50)  NOT NULL,
  locale       VARCHAR(35)  NOT NULL DEFAULT '',
  channel      VARCHAR(20)  NOT NULL DEFAULT '',
  description  TEXT,
  `schema`     LONGTEXT     NOT NULL,
  value        LONGTEXT     NOT NULL,
  status       VARCHAR(20)  NOT NULL,
  version      INT          NOT NULL,
  created_by   VARCHAR(255),
  updated_by   VARCHAR(255),
  created_at   DATETIME(3)  NOT NULL DEFAULT (UTC_TIMESTAMP(3)),
  updated_at   DATETIME(3)  NOT NULL DEFAULT (UTC_TIMESTAMP(3)),
  UNIQUE KEY uq_laci_entries_address (`key`, environment, locale, channel),
  KEY idx_laci_entries_kind (kind, environment),
  CONSTRAINT ck_laci_entries_kind CHECK (kind IN ('CONFIG', 'EMAIL_TEMPLATE', 'MESSAGE_TEMPLATE')),
  CONSTRAINT ck_laci_entries_status CHECK (status IN ('DRAFT', 'PUBLISHED', 'DISABLED')),
  CONSTRAINT ck_laci_entries_channel CHECK (channel IN ('', 'WHATSAPP', 'SMS', 'PUSH', 'IN_APP')),
  CONSTRAINT ck_laci_entries_schema CHECK (JSON_VALID(`schema`)),
  CONSTRAINT ck_laci_entries_value CHECK (JSON_VALID(value))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE IF NOT EXISTS laci_entry_histories (
  id          BINARY(16)  NOT NULL PRIMARY KEY,
  entry_id    BINARY(16)  NOT NULL,
  version     INT         NOT NULL,
  value       LONGTEXT    NOT NULL,
  `schema`    LONGTEXT    NOT NULL,
  status      VARCHAR(20) NOT NULL,
  changed_by  VARCHAR(255),
  changed_at  DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)),
  note        TEXT,
  UNIQUE KEY uq_laci_entry_histories_version (entry_id, version),
  FOREIGN KEY (entry_id) REFERENCES laci_entries (id),
  CONSTRAINT ck_laci_histories_value CHECK (JSON_VALID(value)),
  CONSTRAINT ck_laci_histories_schema CHECK (JSON_VALID(`schema`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
INSERT INTO laci_migrations (version, name) VALUES (1, 'initial schema');
